export function selectLanguage(search='',saved=null){const query=new URLSearchParams(search).get('lang');return ['en','fr'].includes(query)?query:['en','fr'].includes(saved)?saved:'fr';}
export function text(language,key,values={}){const value=TEXT[language]?.[key]??TEXT.en[key];if(value===undefined)throw new Error(`Unknown translation: ${key}`);return value.replace(/\{(\w+)\}/g,(match,name)=>values[name]??match);}
export function phaseText(language,phase){if(!PHASES[phase])throw new RangeError('Unknown phase');return language==='fr'?{...PHASES[phase],...FRENCH_PHASES[phase]}:PHASES[phase];}
export function landmarkText(language,mark){return language==='fr'?(FRENCH_LANDMARKS[mark.id]??mark):mark;}
export function applyTranslations(document,language){
  document.documentElement.lang=language;document.title=text(language,'pageTitle');
  document.querySelector('meta[name="description"]').setAttribute('content',text(language,'metaDescription'));
  for(const [attribute,target] of [['data-i18n',null],['data-i18n-aria','aria-label'],['data-i18n-title','title']]){
    document.querySelectorAll(`[${attribute}]`).forEach(element=>{const value=text(language,element.getAttribute(attribute));if(target)element.setAttribute(target,value);else element.textContent=value;});
  }
}
